CREATE TABLE merchants(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL);
CREATE TABLE memberships(user_id uuid REFERENCES users(id), merchant_id uuid REFERENCES merchants(id), role text NOT NULL CHECK(role IN ('reader','operator','merchant-admin')), PRIMARY KEY(user_id,merchant_id));
CREATE TABLE devices(id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), name text NOT NULL, last_heartbeat timestamptz, revoked boolean NOT NULL DEFAULT false, UNIQUE(id,merchant_id));
CREATE TABLE device_credentials(device_id uuid REFERENCES devices(id), version integer CHECK(version>0), secret text NOT NULL, revoked_at timestamptz, PRIMARY KEY(device_id,version));
CREATE TABLE payments(id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), device_id uuid NOT NULL, idempotency_key text NOT NULL, fingerprint text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0 AND amount_minor<=999999999999), currency char(3) NOT NULL CHECK(currency IN ('INR','USD','EUR')), reference text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(merchant_id,idempotency_key), UNIQUE(id,merchant_id), FOREIGN KEY(device_id,merchant_id) REFERENCES devices(id,merchant_id));
CREATE TABLE commands(id uuid PRIMARY KEY, merchant_id uuid NOT NULL, payment_id uuid NOT NULL UNIQUE, device_id uuid NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','published','completed','expired','unknown')), expires_at timestamptz NOT NULL, published_at timestamptz, completed_at timestamptz, FOREIGN KEY(payment_id,merchant_id) REFERENCES payments(id,merchant_id), FOREIGN KEY(device_id,merchant_id) REFERENCES devices(id,merchant_id));
CREATE TABLE outbox(id uuid PRIMARY KEY, command_id uuid NOT NULL UNIQUE REFERENCES commands(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','leased','published','exhausted','permanent','expired')), payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, owner text, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_claim ON outbox(next_attempt_at,created_at) WHERE status IN ('pending','leased');
CREATE TABLE delivery_attempts(id bigserial PRIMARY KEY, outbox_id uuid NOT NULL REFERENCES outbox(id), lease_token uuid NOT NULL UNIQUE, owner text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, outcome text NOT NULL DEFAULT 'claimed', error text);
CREATE TABLE device_messages(device_id uuid REFERENCES devices(id), message_id uuid, fingerprint text NOT NULL, kind text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(device_id,message_id));
CREATE TABLE receipts(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id), command_id uuid NOT NULL REFERENCES commands(id), credential_version integer NOT NULL, result text NOT NULL CHECK(result IN ('completed','expired')), device_timestamp timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), fingerprint text NOT NULL, conflicting boolean NOT NULL DEFAULT false, FOREIGN KEY(device_id,credential_version) REFERENCES device_credentials(device_id,version));
CREATE INDEX receipts_command ON receipts(command_id);
CREATE TABLE incidents(id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), kind text NOT NULL, resource_id uuid NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), opened_at timestamptz NOT NULL DEFAULT now(), UNIQUE(merchant_id,kind,resource_id));
CREATE TABLE incident_evidence(id uuid PRIMARY KEY, incident_id uuid NOT NULL REFERENCES incidents(id), schema_version integer NOT NULL DEFAULT 1, captured_at timestamptz NOT NULL DEFAULT now(), snapshot jsonb NOT NULL);
CREATE TABLE audit_events(id bigserial PRIMARY KEY, merchant_id uuid REFERENCES merchants(id), user_id uuid REFERENCES users(id), action text NOT NULL, resource_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_status(id text PRIMARY KEY, progressed_at timestamptz NOT NULL, broker_connected boolean NOT NULL, disconnected_since timestamptz);
CREATE INDEX payments_merchant_time ON payments(merchant_id,accepted_at DESC);
CREATE INDEX incidents_merchant_time ON incidents(merchant_id,opened_at DESC);
CREATE INDEX audit_merchant_time ON audit_events(merchant_id,created_at DESC);
CREATE INDEX commands_reconcile ON commands(state,expires_at);
CREATE FUNCTION reject_evidence_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only evidence'; END $$;
CREATE TRIGGER evidence_immutable BEFORE UPDATE OR DELETE ON incident_evidence FOR EACH ROW EXECUTE FUNCTION reject_evidence_change();
CREATE TRIGGER receipts_immutable BEFORE UPDATE OR DELETE ON receipts FOR EACH ROW EXECUTE FUNCTION reject_evidence_change();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_evidence_change();
